tasks.solution:
CREATE TABLE dwh_orders AS
SELECT * FROM orders WHERE order_date < '2026-06-01';

INSERT INTO dwh_orders
SELECT * FROM orders
WHERE order_date > (SELECT MAX(order_date) FROM dwh_orders);

SELECT COUNT(*) AS loaded_orders, MAX(order_date) AS last_date FROM dwh_orders;
